/**
 * Wall-clock fields of `date` in `timeZone`. An unknown zone throws
 * `RangeError` from `Intl` and is not swallowed.
 */
function zonedParts(
  date: Date,
  timeZone: string,
): { year: number; month: number; day: number; hour: number; minute: number; second: number } {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  const bag: Record<string, string> = {};
  for (const part of fmt.formatToParts(date)) {
    if (part.type !== "literal") bag[part.type] = part.value;
  }
  let hour = Number(bag.hour);
  if (hour === 24) hour = 0;
  return {
    year: Number(bag.year),
    month: Number(bag.month),
    day: Number(bag.day),
    hour,
    minute: Number(bag.minute),
    second: Number(bag.second),
  };
}

/** Milliseconds to add to UTC to reach the zone's wall clock at `date`. */
function offsetMs(date: Date, timeZone: string): number {
  const parts = zonedParts(date, timeZone);
  const asUtc = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
    date.getMilliseconds(),
  );
  return asUtc - date.getTime();
}

function pad2(value: number): string {
  return String(value).padStart(2, "0");
}

/** `YYYY-MM-DD` plus or minus a number of calendar days, ignoring DST. */
function shiftCalendarDate(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const shifted = new Date(Date.UTC(year!, month! - 1, day! + days));
  return shifted.toISOString().slice(0, 10);
}

/**
 * UTC instants that read as `hour:00:00` on `ymd` in `timeZone`. A spring-forward
 * gap yields none; a fall-back hour yields both occurrences.
 */
function instantsAtLocalHour(ymd: string, hour: number, timeZone: string): Date[] {
  const [year, month, day] = ymd.split("-").map(Number);
  const guess = Date.UTC(year!, month! - 1, day!, hour, 0, 0, 0);
  const first = guess - offsetMs(new Date(guess), timeZone);
  const second = guess - offsetMs(new Date(first), timeZone);
  const unique = [...new Set([first, second])];
  return unique
    .map((ms) => new Date(ms))
    .filter((candidate) => {
      const parts = zonedParts(candidate, timeZone);
      const candidateYmd = `${parts.year}-${pad2(parts.month)}-${pad2(parts.day)}`;
      return (
        candidateYmd === ymd &&
        parts.hour === hour &&
        parts.minute === 0 &&
        parts.second === 0
      );
    });
}

/** Local hour of `reference` on the workspace clock. */
export function localHour(reference: Date, timeZone: string): number {
  return zonedParts(reference, timeZone).hour;
}

/** `YYYY-MM-DD` calendar date of an instant in `timeZone`. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = zonedParts(parseIso(value), timeZone);
  return `${parts.year}-${pad2(parts.month)}-${pad2(parts.day)}`;
}

/**
 * UTC instant at which the calendar day containing `reference` began in
 * `timeZone`, written the same way `toIsoTimestamp` writes every other stamp.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const ymd = localDate(toIsoTimestamp(reference), timeZone);
  const hits = instantsAtLocalHour(ymd, 0, timeZone);
  if (hits.length > 0) {
    return toIsoTimestamp(hits.reduce((earliest, hit) => (hit < earliest ? hit : earliest)));
  }
  // A zone that skips local midnight: first instant whose calendar date is `ymd`.
  const [year, month, day] = ymd.split("-").map(Number);
  const probe = Date.UTC(year!, month! - 1, day!, 12, 0, 0, 0);
  let lo = probe - 36 * HOUR_MS;
  let hi = probe + 36 * HOUR_MS;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (localDate(toIsoTimestamp(new Date(mid)), timeZone) < ymd) lo = mid + 1;
    else hi = mid;
  }
  return toIsoTimestamp(new Date(lo));
}

/**
 * True once the workspace calendar day that contains `dueAt` has ended.
 * On that day itself the issue is not overdue, whatever time `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

