/**
 * The window a digest covers. It ends at the most recent local `hour:00` at
 * or before `reference` (today's if that hour has passed, otherwise
 * yesterday's) and starts at the same local hour on the previous calendar
 * day. Across a DST change that span is 23 or 25 hours.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const end = mostRecentLocalHour(reference, digestHourUtc, timeZone);
  const endDay = localDate(toIsoTimestamp(end), timeZone);
  const startDay = shiftCalendarDate(endDay, -1);
  const startHits = instantsAtLocalHour(startDay, digestHourUtc, timeZone);
  const start =
    startHits.length > 0
      ? startHits.reduce((latest, hit) => (hit > latest ? hit : latest))
      : new Date(parseIso(startOfLocalDay(new Date(end.getTime() - 20 * HOUR_MS), timeZone)).getTime());

  return {
    start: toIsoTimestamp(start),
    end: toIsoTimestamp(end),
  };
}

/** Latest `hour:00` on the workspace clock that is still at or before `reference`. */
function mostRecentLocalHour(reference: Date, hour: number, timeZone: string): Date {
  const today = localDate(toIsoTimestamp(reference), timeZone);
  const todayHits = instantsAtLocalHour(today, hour, timeZone).filter(
    (hit) => hit.getTime() <= reference.getTime(),
  );
  if (todayHits.length > 0) {
    return todayHits.reduce((latest, hit) => (hit > latest ? hit : latest));
  }
  const yesterday = shiftCalendarDate(today, -1);
  const yesterdayHits = instantsAtLocalHour(yesterday, hour, timeZone);
  if (yesterdayHits.length > 0) {
    return yesterdayHits.reduce((latest, hit) => (hit > latest ? hit : latest));
  }
  throw new RangeError(`No local ${hour}:00 near ${today} in ${timeZone}`);
}

