/**
 * UTC instant at which the calendar day containing `reference` began in
 * `timeZone`, written the same way `toIsoTimestamp` writes every other stamp.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const ymd = localDate(toIsoTimestamp(reference), timeZone);
  const hits = instantsAtLocalHour(ymd, 0, timeZone);
  if (hits.length > 0) {
    return toIsoTimestamp(hits.reduce((earliest, hit) => (hit < earliest ? hit : earliest)));
  }
  // A zone that skips local midnight: first instant whose calendar date is `ymd`.
  const [year, month, day] = ymd.split("-").map(Number);
  const probe = Date.UTC(year!, month! - 1, day!, 12, 0, 0, 0);
  let lo = probe - 36 * HOUR_MS;
  let hi = probe + 36 * HOUR_MS;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (localDate(toIsoTimestamp(new Date(mid)), timeZone) < ymd) lo = mid + 1;
    else hi = mid;
  }
  return toIsoTimestamp(new Date(lo));
}

