it("treats a due date as overdue only after its calendar day has ended", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  // 14:59Z is still 14 Mar in Tokyo; 15:00Z is 15 Mar there, the reference's local day.
  expect(isOverdue(iso("2026-03-14T14:59:00.000Z"), REFERENCE, "Asia/Tokyo")).toBe(true);
  expect(isOverdue(iso("2026-03-14T15:00:00.000Z"), REFERENCE, "Asia/Tokyo")).toBe(false);
});

