input.new_string:
  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });

  it("names the calendar date in the workspace zone", () => {
    expect(localDate(iso("2026-03-15T15:00:00.000Z"), "UTC")).toBe("2026-03-15");
    expect(localDate(iso("2026-03-15T15:00:00.000Z"), "Asia/Tokyo")).toBe("2026-03-16");
  });

  it("returns the UTC instant when the local day started", () => {
    expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
    expect(startOfLocalDay(new Date("2026-03-15T16:00:00.000Z"), "Asia/Tokyo")).toBe(
      "2026-03-15T15:00:00.000Z",
    );
  });

  it("spans 23 hours across a spring-forward and 25 across a fall-back", () => {
    const spring = digestWindow(9, new Date("2026-03-08T14:00:00.000Z"), "America/New_York");
    expect(spring.end).toBe("2026-03-08T13:00:00.000Z");
    expect(spring.start).toBe("2026-03-07T14:00:00.000Z");

    const fall = digestWindow(9, new Date("2026-11-01T15:00:00.000Z"), "America/New_York");
    expect(fall.end).toBe("2026-11-01T14:00:00.000Z");
    expect(fall.start).toBe("2026-10-31T13:00:00.000Z");
  });
});

